	title 'Text Tools           GS ROM 3.0'*****************************************************************			   **	    Text Tools		   **			   **********************************************************************************************************************************			   **	Copyright (C) 1985-1989	   **	All Rights Reserved		   **	Apple Computer, Inc.	   **			   ***************************************************************************************************************************************** Change history** 21 March 88	Steven Glass** Device error code was being returned in 8-bit mode rather* than in 16 bit mode in two calls: TextCtrl and TextStat.** 02 Aug 88	Steven Glass** InitTextDev ignored errors from TTDispatch.   TTDsptch did not* set the carry register and a-reg for non-error cases correctly.** 15 Nov 88	Konstantin Othmer** Added slot arbiter calls.  Now slot number is stored as number between*  1-15 instead of 1-7.  The conversion is done is setdevice routines.** 01 Feb 89	Harry Yee** Changed the version number from $0200 to $8300 (3.0P)** 4-Nov-91	Dave Lyons** Make GetInputDevice, GetOutputDevice, GetErrorDevice return* clean device types (no garbage in the high byte).  (Common* patch in GetDev--stz Type.)***********************************************************************	include 'all.macros'	include '::sys.equs.asm'	include 'e16.memory'KSW	equ $000038CSW	equ $000036ANDin	equ $E115AAORin	equ ANDin+1ANDout	equ ORin+1ORout	equ ANDout+1ANDerr	equ ORout+1ORerr	equ ANDerr+1DevType	equ ORerr+1DevPtr	equ DevType+3InDevPtr	equ DevPtrOutDevPt	equ InDevPtr+4ErrDevPt	equ OutDevPt+4ErrHook	equ ErrDevPt+4;; Slot Arbiter entry point;Slot_Arbiter	equ $E10208;-----------------------------------------------------------;; Error Codes;IllegalDeviceError	equ $0C01;-----------------------------------------------;;    Imported addresses;;-----------------------------------------------	IMPORT EndCall0	IMPORT EndCall10	IMPORT EndCall2	IMPORT EndCall4	IMPORT EndCall6	IMPORT ErrOut10	IMPORT ErrOut2	IMPORT ErrOut4	IMPORT ErrOut8	IMPORT FFEntry	IMPORT FWentry	IMPORT e1vectors	IMPORT oEndCall0	IMPORT oEndCall2	IMPORT oEndCall4	IMPORT oErrOut2	IMPORT oErrOut4;-----------------------------------------------;;   Forward addresses and entries;;-----------------------------------------------	ENTRY EWrBlk	ENTRY EWrChar	ENTRY EWrCstr	ENTRY EWrLine	ENTRY EWrStr	ENTRY GetErrDev	ENTRY GetErrGP	ENTRY GetInDev	ENTRY GetInGP	ENTRY GetItIn	ENTRY GetOutDev	ENTRY GetOutGP	ENTRY MakeDDCB	ENTRY RdBlk	ENTRY RdChar	ENTRY RdLine	ENTRY SendOut	ENTRY SetErrDev	ENTRY SetErrGP	ENTRY SetInDev	ENTRY SetInGP	ENTRY SetOutDev	ENTRY SetOutGP	ENTRY TTDsptch	ENTRY TTInit	ENTRY TTStat	ENTRY TextCallTable	ENTRY TextCtrl	ENTRY TextInit	ENTRY TextRes	ENTRY TextShut	ENTRY TextSp1	ENTRY TextSp2	ENTRY TextStat	ENTRY TextStrt	ENTRY TextVer	ENTRY WrAStr	ENTRY WrBlk	ENTRY WrChar	ENTRY WrCstr	ENTRY WrLinErr	ENTRY WrLine	ENTRY WrString	ENTRY readit****************************************************************** Record of changes	to the Text Tool Set.....** Revision     Date	    Description	               Who*              3-06-86  Initial release	               RBM*              3-26-86  Beta 1.0	               RBM*              4-01-86  New Text Tools	               RBM*****************************************************************	EXPORT TextCallTableTextCallTable	PROCHere		; 	DC.L (TheEnd-Here)/4 ; num calls +1	DC.L TTInit-1	; PowerUp Initialization	DC.L TextStrt-1	; application startup	DC.L TextShut-1	; application shutdown	DC.L TextVer-1	; version number	DC.L TextRes-1	; Misc. Tools Reset	DC.L TTStat-1	; Reserved	DC.L TextSp1-1	; Reserved	DC.L TextSp2-1	; Reserved	DC.L SetInGP-1	; Set input global parameters	DC.L SetOutGP-1	; set output global	parameters	DC.L SetErrGP-1	; set error output globals	DC.L GetInGP-1	; get input global parameters	DC.L GetOutGP-1	; get output global	parameters	DC.L GetErrGP-1	; get error output globals	DC.L SetInDev-1	; set input device	DC.L SetOutDev-1	; set output device	DC.L SetErrDev-1	; set error device	DC.L GetInDev-1	; get input device	DC.L GetOutDev-1	; get output device	DC.L GetErrDev-1	; get error device	DC.L TextInit-1	; initialize text device	DC.L TextCtrl-1	; control text device	DC.L TextStat-1	; return text device status	DC.L WrChar-1	; write character to device	DC.L EWrChar-1	; write character to error device	DC.L WrLine-1	; write line to output device	DC.L EWrLine-1	; write line to error device	DC.L WrString-1	; write string to device	DC.L EWrStr-1	; write string to error device	DC.L WrBlk-1	; write text to output device	DC.L EWrBlk-1	; write text to error device	DC.L WrCstr-1	; write C-String to	output device	DC.L EWrCstr-1	; write C-String to	error device	DC.L RdChar-1	; read character from input device	DC.L RdBlk-1	; read block from input device	DC.L RdLine-1	; read line from input deviceTheEnd		; 	ENDP;          copy  text.tools/glue****************************************************************** STANDARD TOOL CALLS................................** BOOTINIT:    Sets	the default parameters as follows*              Input, Output & Error Device type  = BASIC in slot #3*              AND masks set to $FF*              OR masks set to $80** STARTUPINIT: Does	nothing** SHUTDOWN:    Does	nothing** VERSION:     Returns the current version number** RESET:       Sets	the BASIC input & ouput hooks back*              Sets	the default parameters as follows*              Input & Output Device type = BASIC in slot #3*              AND masks set to $FF*              OR masks set to $80** STATUS:      Always returns with ACTIVE** SPARE1:      Does	nothing** SPARE2:      Does	nothing*****************************************************************	EXPORT TTInitTTInit	PROC	; Tool Boot Initialization	EXPORT TextResTextRes		;       	phb	pea ANDin/256	plb	plb	ldx #$000E	; initialize or mask and loc.	EXPORT TTPloopTTPloop		; 	stz |DevType,x	dex	dex	bpl TTPloop	lda #$80FF	; set global AND masks	sta |ANDin	sta |ANDout	sta |ANDerr	lda #0003	sta |InDevPtr	; devices in slot 3	sta |OutDevPt	sta |ErrDevPt	plb	jmp oEndCall0	EXPORT TextStrtTextStrt		;       ; Tool Start Up	EXPORT TextShutTextShut		;       ; Tool Shut	Down	EXPORT TextSp1TextSp1		;       	EXPORT TextSp2TextSp2		;       	jmp oEndCall0	ENDP	EXPORT TextVerTextVer	PROCRTL1	equ 1RTL2	equ RTL1+3Result	equ RTL2+3Version	equ $0300	; current version number	lda #version	; get MT version #	sta Result,s	; pass to caller	jmp oEndCall0	ENDP	EXPORT TTStatTTStat	PROCrtl1	equ 1rtl2	equ rtl1+3TheStatus	equ rtl2+3	lda #$FFFF	; indicate tool active	sta TheStatus,s	jmp oEndCall0	ENDP;          copy  text.tools/globals	EXPORT SetInGPSetInGP	PROC****************************************************************** Set Input Global Parameters**      Input   Word	    AND mask*      Input   Word	    OR mask* sp->*****************************************************************OrigDir	equ 1rtl1	equ OrigDir+2rtl2	equ rtl1+3maskor	equ rtl2+3maskand	equ maskor+2	ldx #0	; index input globals	EXPORT SetGSetG		;       	phd	; save direct page	tsc	; set stack to zp	tcd	phb	pea ANDin/256	plb	plb	sep #$20	; 8 bit 'm'	longa off	lda maskor	; set input OR mask	sta |ORin,x	lda maskand	; set input AND mask	sta |ANDin,x	plb	rep #$20	; 16 bit 'm'	longa on	jmp EndCall4	ENDP	EXPORT SetOutGPSetOutGP	PROC****************************************************************** Set Output Global	Parameters**      Input   Word	    AND mask*      Input   Word	    OR mask* sp->*****************************************************************	ldx #2	; index output globals	bra SetG	ENDP	EXPORT SetErrGPSetErrGP	PROC****************************************************************** Set Error Output Global Parameters**      Input     Word     AND mask*      Input     Word     OR mask* sp->*****************************************************************	ldx #4	; index error globals	bra SetG	ENDP	EXPORT GetInGPGetInGP	PROC****************************************************************** Get Input Global Parameters**      Input     Word     Space for result*      Input     Word     Space for result* sp->**      Output    Word     AND mask for input device*      Output    Word     OR mask for input device* sp->*****************************************************************OrigDir	equ 1rtl1	equ OrigDir+2rtl2	equ rtl1+3maskor	equ rtl2+3maskand	equ maskor+2	ldx #0	; index input globals	EXPORT GetGGetG		;       	phd	; turn stack into zp	tsc	tcd	phb	pea ANDin/256	plb	plb	sep #$20	; 8 bit 'm'	longa off	lda |ORin,x	; get OR mask	sta maskor	lda |ANDin,x	; get AND mask	sta maskand	rep #$20	; 16 bit 'm'	longa on	plb	jmp EndCall0	ENDP	EXPORT GetOutGPGetOutGP	PROC****************************************************************** Get Output Global	Parameters**      Input     Word     Space for result*      Input     Word     Space for result* sp->**      Output    Word     AND mask for output device*      Output    Word     OR mask for output device* sp->*****************************************************************	ldx #2	; index output globals	bra GetG	ENDP	EXPORT GetErrGPGetErrGP	PROC****************************************************************** Get Error Output Device Global Parameters**      Input     Word     Space for result*      Input     Word     Space for result* sp->**      Output    Word     AND mask for error device*      Output    Word     OR mask for error device* sp->*****************************************************************	ldx #4	; index error globals	bra GetG	ENDP	EXPORT SetInDevSetInDev	PROC****************************************************************** Set INPUT device type and location.**      Input     Word       Device type*      Input     LongWord   Device location (Addr or Slot)* sp->*** Change History:** Nov. 16 '88	Konstantin Othmer** If it's a slot (and not a ram driver), we check* whether or not the slot is internal or external.  If it's external,* we add 8 to the slot number because this is how the arbiter numbers* slots.*****************************************************************OrigDB	equ 1OrigDir	equ OrigDB+1rtl1	equ OrigDir+2rtl2	equ rtl1+3Location	equ rtl2+3Type	equ Location+4	ldx #0	; this is the input	dev	EXPORT SetDevSetDev		; 	phd	; turn stack into zp	phb	tsc	tcd	pea DevType/256	; point at parameters	plb	plb	txa	asl a	asl a	tay	sep #$20	; 8 bit 'm'	lda type	; set device type	sta |DevType,x	rep #$20	; 16 bit 'm'	lda Location	; set location	sta |DevPtr,y	lda Location+2	sta |DevPtr+2,y;; If it's a RAM based driver, we do nothing.;  If it's a slot number, we leave numbers between 9 and 15 alone (hopefully user ;   knows about arbiter slot numbering), but we convert numbers between 1 and 7 to;  1-15 depending on whether or not the slot is currently internal or external.;  If internal we leave alone.  We add 8 to external slots.;	lda type	cmp #2	beq DevPtrOK	;Ram based driver	lda |DevPtr,y	;get slot number	cmp #8	;is it an old slot number (7 or less)?	bcs DevPtrOK	;branch if no;; Here we check to see if the slot is internal or external;	phy	;save index		pha	;save slot number	lda #$8000	;get slot configuration in x	jsl slot_arbiter	;	txa	;bit encoded slot information to a	plx	;get saved slot number	ply	;restore index		lsr a	;alignment	DevLoop	lsr a	;get relevent bit in carry	dex	bne DevLoop	bcs DevPtrOK	;slot is internal and DevPtr is OK;;It's an external slot.  Add 8 to slot number and save in DevPtr;	lda |DevPtr,y	;slot number	ora #$0008	;bit 4 indicates external	sta |DevPtr,y	DevPtrOK	plb	jmp EndCall6	EXPORT SetOutDevSetOutDev		;       ****************************************************************** Set OUTPUT device	type and location.**      Input     Word       Device type*      Input     LongWord   Device location (Addr or Slot)* sp->*****************************************************************	ldx #1	; this is the Output dev	bra SetDev	EXPORT SetErrDevSetErrDev		;       ****************************************************************** Set ERROR device type and location.**      Input     Word       Device type*      Input     LongWord   Device location (Addr or Slot)* sp->*****************************************************************	ldx #2	; this is the Error	dev	bra SetDev	EXPORT GetInDevGetInDev		;       ****************************************************************** Get INPUT device type and location.**      Input      Word      Space for result*      Input      LongWord  Space for result* sp->**      Output     Word      Device type*      Output     LongWord  Device location (Addr or Slot)* sp->*****************************************************************	ldx #0	; this is the input	dev	EXPORT GetDevGetDev		; 	phd	; turn stack into zp	phb	tsc	tcd*** 4-Nov-91 DAL -- zero the Type result parameter (high byte was garbage)	stz Type*** end 4-Nov-91 DAL	pea DevType/256	; point at parameters	plb	plb	txa	asl a	asl a	tay	sep #$20	; 8 bit 'm'	lda |DevType,x	; get the device type	sta Type	rep #$20	; 16 bit 'm'	lda |DevPtr,y	; get the device location	sta Location	lda |DevPtr+2,y	sta Location+2	lda Type	cmp #2	;Ram based driver?	beq GetDone	;not a slot - we're done;; It's a slot: convert it to number between 1 and 7 (8-15 is external);	lda Location	and #$07	;convert to 1-7	sta LocationGetDone	plb	jmp EndCall0	EXPORT GetOutDevGetOutDev		;       ****************************************************************** Get OUTPUT device	type and location.**      Input      Word      Space for result*      Input      LongWord  Space for result* sp->**      Output     Word      Device type*      Output     LongWord  Device location (Addr or Slot)* sp->*****************************************************************	ldx #1	; this is the output dev	bra GetDev	EXPORT GetErrDevGetErrDev		;       ****************************************************************** Get ERROR device type and location.**      Input      Word      Space for result*      Input      LongWord  Space for result* sp->**      Output     Word      Device type*      Output     LongWord  Device location (Addr or Slot)* sp->*****************************************************************	ldx #2	; this is the error	dev	bra GetDev	ENDPTextInit	PROC****************************************************************** TEXT DEVICE INITIALIZATION**      Input     Word     Device to initialize* sp->	      0 = Input device*	      1 = Output device*	      2 = Error output device	  ** If the device is a basic device, the I/O hooks are set* to the init entry	for the device being called.** Modification History:** 11 Sep 86    RBM	    Updated to handle save/restore of I/O*	    hooks when initing an error device.** 02 Aug 88    SEG      Look for error from TTDispatch** 15 Oct 88    SEG      Add call to you've got to be kidding.** 31 Oct 88    SEG      Trick or Treat.  Fix stack imbalance in *	    error code:  extra word was left on stack*	    when input was out of range.******************************************************************;-----------------------------------------------------------;; Yet another horrible hack from the people who brought you...;; This is the only time we can be sure that the OS; will call the ROM after the drivers are back in place and; before the application runs.;; So we call YouveGotToBeKidding and hope for the best.; IF RAMVERSION<>1 THEN	import YouveGotToBeKidding	jsl YouveGotToBeKidding ENDIF;-----------------------------------------------------------hookspace	equ 1OrigDBR	equ hookspace+2OrigDir	equ OrigDBR+1rtl1	equ OrigDir+2rtl2	equ rtl1+3device	equ rtl2+3	phd	; Save D	phb	; save B	pea $0000	; Push 0	tsc	; turn stack into zp	tcd		lda Device	cmp #3	;input, output, or error ?	bcc DeviceOK	ldx #IllegalDeviceError ; illegal device error	pla	; pull off that zero	plb	; restore b	pld	; restore d	jmp oErrOut2	; return the errorDeviceOK	sep #$30 	; switch to 8 bit mode	longa off	longi off	pea DevType/256	; point at device type	plb	plb	tay	; index to get type 	lda |DevType,y	; get device type	bne NotBASIC	; if not basic, leave hooks	tya	; point at device pointer	asl a	asl a	tax	rep #$20	; 16 bit 'm'	longa on	lda |DevPtr,x	; get slot # = $000n;; since slot arbiter slot numbers go from 1-15, we have to convert to 1-7;	and #7;		xba	; $0n00	ora #$C000	; build $Cn00	cpy #0	; is it the input device?	bne SetOutHk	; no	sta >KSW	; set input hook	bra HookSetSetOutHk		; 	cpy #2	; is this an error device?	bne noterrdev	; no	pha	; save new output hook	lda >csw	; and save current output hook	sta hookspace	planoterrdev		; 	sta >CSW	; set output hookHookSet		; 	sep #$20	; 8 bit 'm'	longa offNotBASIC		; 	lda #0	; its an init call	jsr MakeDDCB	; build the DDCB	pha	; save the real DDCB	pha	and #%01111111	; init is always a standard device	rep #$30	; 16 bit 'm' & 'x'	longa on	longi on	pea $0000	; init character	jsr TTDsptch	; dispatch to device	tax	; put any error code into x-reg	pla	; get status and ignore it	pla	; get the real DDCB	php	; save dispatch error flag	and #$00C0	; Y = Error and not	basic	cmp #$0080	; was it a basic error call?	bne norestore	; no	lda >csw	; get error device hook	sta >ErrHook	; and save for error dispatches	lda hookspace	sta >csw	; restore basic output hooknorestore		plp	; get dispatch error flag	pla	; clean off hookspace	plb	pld	jmp oErrOut2	; rely on x being correct!	ENDP	EXPORT TextCtrlTextCtrl	PROC****************************************************************** TEXT DEVICE CONTROL**      Input   Word	    Device to control*      Input   Word	    Control code* sp->** Change history** 21 March 88	Steven Glass** Device error code was being returned in 8-bit mode rather* than in 16 bit mode.******************************************************************OrigDB	equ 1OrigDir	equ OrigDB+1rtl1	equ OrigDir+2rtl2	equ rtl1+3CtrlCode	equ rtl2+3Device	equ CtrlCode+2	phd	; turn stack into zp	phb	tsc	tcd	sep #$30	; 8 bit 'm' and 'x'	longa off	longi off	lda device	; get device type	cmp #3	; is is a legal type?	blt DevOK	; yes	EXPORT TypeErrTypeErr		; 	rep #$30	longa on	longi on	ldx #IllegalDeviceError	; else bad dev error	plb	pld	EXPORT CtrlErrCtrlErr		; 	jmp oErrOut2	longa off	longi off	EXPORT DevOKDevOK		; 	tay	; index to get type	pea DevType/256	plb	plb	lda |DevType,y	; error if its a BASIC device	beq TypeErr	lda #4	; this is a control	call	jsr MakeDDCB	; build the DDCB	rep #$30	; 16 bit 'm' and 'x'	longa on	longi on	ldx CtrlCode	; get control code	phx	jsr TTDsptch	; dispatch to device	plx	; get status	plb	pld	bcs CtrlErr	; if error occured	jmp oEndCall4	ENDP	EXPORT TextStatTextStat	PROC****************************************************************** TEXT DEVICE STATUS**      Input   Word	    Device to request status*      Input   Word	    Request code* sp->*** Change history** 21 March 88	Steven Glass** Device error code was being returned in 8-bit mode rather* than in 16 bit mode.*****************************************************************OrigDB	equ 1OrigDir	equ OrigDB+1rtl1	equ OrigDir+2rtl2	equ rtl1+3StatCode	equ rtl2+3Device	equ StatCode+2	phd	; turn stack into zp	phb	tsc	tcd	sep #$30	; 8 bit 'm' and 'x'	longa off	longi off	lda device	; get device type	cmp #3	; is it a legal device	blt DevOK	; yes	rep #$30	; added 3/21	longa on	; added 3/21	longi on	; added 3/21	ldx #IllegalDeviceError	; bad dev error	plb	pldStatErr		; 	jmp oErrOut4	longa off	; added 3/21	longi off	; added 3/21DevOK		; 	tay	; index to get type	lda #3	; this is a status call	jsr MakeDDCB	; build the DDCB	rep #$30	; 16 bit 'm' and 'x'	longa on	longi on	ldx StatCode	; get the stat rqst	code	phx	jsr TTdsptch	; dispatch to device driver	plx	; get status	plb	pld	bcs StatErr	jmp oEndCall4	ENDP;          copy  text.tools/write.stuff	EXPORT WrCharWrChar	PROC****************************************************************** WRITE CHARACTER:** Input     Byte	 Null* Input     Byte	 Character*****************************************************************	longa on	longi onrtl1	equ 1rtl2	equ rtl1+3TheChar	equ rtl2+3	clv	; set OUTPUT flag	bvc WChar	EXPORT EWrCharEWrChar		;       	sep #%01000000	; set INPUT flagWChar		; 	lda TheChar,s	; get character	jsr SendOut	; and send to device	jml oErrOut2	ENDP****************************************************************** SendItOut** Sends the char in	the A-reg out the device specified by the* overflow flag after appropriate masking of the character.** ENTRY:*        V=0   Device is the output device*        V=1   Device is the error output device*        A-reg Character in low byte** EXIT:*        V=0   Device was the output device*        V=1   Device was the error output device*        C=0   No error resulted from dispatch*        C=1   Error resulted from dispatch*        X-reg Error code returned from	device*        A-reg trashed*** Change History** 09 Aug 88	Steven Glass** Comments above said error code came back in a-reg.  It* comes back in x-reg.*****************************************************************	EXPORT SendOutSendOut	PROC	longa on	longi on	bvs ESend	; if its an error output	and >ANDout	; mask character with globals	ora >ORout	ldy #1	; for output device	Y=1	bra SendChar	EXPORT ESendESend		; 	and >ANDerr	; mask with globals	ora >ORerr	ldy #2	; for error device Y=2	EXPORT SendCharSendChar		; 	pha	; put the data word	on the stack	phy	; save type	lda #2	; Write or Output call	sep #$30	; 8 bit 'm' and 'x'	jsr MakeDDCB	; build DDCB	rep #$30	; 16 bit 'm' and 'x'	ply	; restore type	jsr TTdsptch	; call that thing	sep #$20	; 8 bit 'm'	longa off	tya	; get back DDCB	lsr a	; STD/ERR to bit 6	and #%01000000	; only want device type	clv	php	ora 1,s	sta 1,s	; restore V=type	plp	rep #$20	; 16 bit 'm'	longa on	bcs FixError	ldx #0	bra CleanStackFixError	txa	ora #$0C00	taxCleanStack	pla	; clean up our mess	rts	; all done	ENDP	EXPORT WrLineWrLine	PROC****************************************************************** WRITE LINE** Input     LongWord     Pointer* This adds a CR/LF	to the end of the string*****************************************************************	longa on	longi on	clv	; set OUTPUT flag	bvc WLine	EXPORT EWrLineEWrLine		;       	sep #%01000000	; set ERROR flag	EXPORT WLineWLine		; 	jsr WrAStr	; send text string	bcs WrLinErr	; if error occured	lda #13	; now send a CR	jsr SendOut	bcs WrLinErr	; if error occured	tya	; get DDCB	and #%01000000	; want driver type	beq NoLF	; no LF if BASIC device	lda #10	; no send a LF	jsr SendOut	EXPORT WrLinErrWrLinErr		;       	EXPORT NoLFNoLF		; 	jml oErrOut4	ENDP	EXPORT WrStringWrString	PROC****************************************************************** WRITE STRING** Input     LongWord     Pointer*****************************************************************	longa on	longi on	clv	; set OUTPUT flag	bvc WStr	EXPORT EWrStrEWrStr		;       	sep #%01000000	; set error flag	EXPORT WStrWStr		; 	jsr WrAStr	; send ASCII string	jmp WrLinErr	; if error occured	ENDP	EXPORT WrAStrWrAStr	PROC****************************************************************** WrAString** Internal routine for use by WrLine and WrString.*****************************************************************	longa on	longi onOrigDir	equ 1count	equ OrigDir+2RTSadr	equ count+2rtl1	equ RTSadr+2rtl2	equ rtl1+3TextPtr	equ rtl2+3	pha	; put extra word on	stack for count	phd	tsc	tcd	lda [TextPtr]	; get count byte	and #$00FF	; limit to 256	inc a	sta Count	ldy #1	; index past count byte	EXPORT textlooptextloop		; 	cpy Count	; done ?	beq AllDone	; yes	LDA [TextPtr],y	; get ascii data	phy	; save string index	jsr SendOut	; send character	ply	; restore string index	iny	; and point at next	character	bcs AStrErr	; if error occured	bra TextLoop	; else go send next	character	EXPORT AllDoneAllDone		; 	clc	; clear error flag	EXPORT AStrErrAStrErr		; 	pld	; restore direct	pla	; clean off word	rts	ENDP	EXPORT WrBlkWrBlk	PROC****************************************************************** WRITE BLOCK:** Input     LongWord     Pointer* Input     Word	     Offset* Input     Word	     Count*****************************************************************	longa on	longi onOrigDir	equ 1RTL1	equ OrigDir+2RTL2	equ RTL1+3Count	equ RTL2+3Offset	equ Count+2TextPtr	equ Offset+2Counter	equ Offset	clv	; set OUTPUT flag	bvc WBlk	EXPORT EWrBlkEWrBlk		;       	sep #%01000000	; set ERROR flag	EXPORT WBlkWBlk		; 	phd	; turn stack into zp	tsc	tcd	php	; save entry flag	clc	; ddr = addr + offset	lda TextPtr	adc Offset	sta TextPtr	lda TextPtr+2	; Fixed 4 Sep 86 to	work if crosses	adc #0	; bank boundry. RBM	sta TextPtr+2	plp	; restore entry flag	stz Counter	; init # chars senttextloop	ldy Counter	; get # chars sent	cpy Count	; done?	beq AllDone	; yes	LDA [TextPtr],y	; else get character	jsr SendOut	; and send to device	bcs TextErr	; exit if device error	inc Counter	; point at next character	bra TextLoopAllDone		; TextErr		; 	jml ErrOut8	ENDP	EXPORT WrCstrWrCstr	PROC****************************************************************** WRITE C STRING** Input     LongWord     Pointer*** Change History** 09 Aug 88	Steven Glass** When null string was passed, an error code equal to the* call number was accidently returned.******************************************************************	longa on	longi onOrigDir	equ 1RTL1	equ OrigDir+2RTL2	equ RTL1+3TextPtr	equ RTL2+3	clv	; set OUTPUT flag	bvc WCStr	EXPORT EWrCStrEWrCStr		;       	sep #%01000000	; set ERROR flag	EXPORT WCStrWCStr		; 	phd	; turn stack into zp	tsc	tcd	ldx #0	; init error code for null string case (SEG 09 Aug 88)	ldy #0	; init string pointerTextLoop		; 	lda [TextPtr],y	; get C-String ASCII	and #$00FF	; low byte only	beq AllDone	; $00 is string terminator	phy	; save string pointer	jsr SendOut	; send to Pascal device	ply	; restore string pointer	iny	; and point at next	char	bcs CStrErr	; if error occured,	exit	bra TextLoop	; else send next characterAllDone		; CStrErr		; 	jml ErrOut4	ENDP;          copy  text.tools/read.stuff	EXPORT RdCharRdChar	PROC****************************************************************** READ CHARACTER:** Input     Word	 Space for result* Input     Word	 Echo flag (1=echo)* Output    Word	 Character*****************************************************************	longa on	longi onOrigDir	equ 1rtl1	equ OrigDir+2rtl2	equ rtl1+3echo	equ rtl2+3TheChar	equ Echo+2	phd	; turn stack into zp	tsc	tcd	jsr GetItIn	; Read character	bcs RCharErr	; if error occured	and >ANDin	; mask character with globals	ora >ORin	sta TheChar	; and store character to stack	ldy echo	; is echo active ?	beq NoEcho	clv	; to the output device	pha	; character to stack	_WriteChar	; and send it outNoEcho		; 	jmp EndCall2	EXPORT RCharErrRCharErr		; 	jmp ErrOut2	ENDP	EXPORT GetItInGetItIn	PROC****************************************************************** GetItIn*****************************************************************	longa on	longi on	ldy #0	; for input device Y=0	pea $0000	; put room on the stack	sep #$30	; 8 bit 'm'	longa off	lda #1	; this is a read call	jsr MakeDDCB	; build DDCB byte	rep #$30	; 16 bit 'm'	longa on	jsr TTdsptch	; call the driver	sep #$30	; 8 bit 'm' and 'x'	longa off	longi off	tya	; get back DDCB	asl a	and #%01000000	; only want driver type	clv	php	ora 1,s	sta 1,s	plp	rep #$30	; 16 bit 'm' and 'x'	longa on	longi on	pla	; get result	rts	; all done	ENDP	EXPORT RdBlkRdBlk	PROC****************************************************************** READ BLOCK:** Input     LongWord Pointer* Input     Word	 Offset* Input     Word	 Count (Max.)* Input     Word	 Echo flag (1=echo)*****************************************************************	longa on	longi onOrigDir	equ 1Rtl1	equ OrigDir+2Rtl2	equ Rtl1+3echo	equ Rtl2+3count	equ echo+2offset	equ count+2RXcount	equ offsetpointer	equ offset+2	phd	; save direct page	tsc	; and turn stack into zp	tcd	php	; save type	clc	; add offset to pointer	lda offset	adc pointer	sta pointer	lda #0	; (32 bit add)	adc pointer+2	sta pointer+2	plp	; restore type	stz RXcount	; clear count received	EXPORT RdBlk0RdBlk0		; 	pha	; room for result	lda echo	; pass echo flag to	rdchar	pha	jsl readit	; read character	bcs RdBlkErr	; if error occured	phb	; and data bank	clc	inc RXcount	; incr received count	ldx pointer	; move pointer to X	reg	sep #$20	; 8 bit 'm'	longa off	lda pointer+2	; get bank	pha	; set pointer bank	plb	lda 2,s	; get character	sta |0,x	; write to buffer	rep #$20	; 16 bit 'm'	longa on	plb	; restore bank & direct page	pla	; remove character	inc Pointer	; point at next buffer location	bne NoPtrOv	; if no buffer overflow	inc Pointer+2	EXPORT NoPtrOvNoPtrOv		; 	lda RxCount	; rcvd count = maximum ?	cmp count	; count = maximum ?	bne RdBlk0	; no, get more	EXPORT RdBlk2RdBlk2		; 	jmp EndCall10	; all done	EXPORT RdBlkErrRdBlkErr		; 	pla	; clean up stack	jmp ErrOut10	; oops!!!	EXPORT ReadItReadIt		;       	jsl RdChar	; go read character	rtl	ENDP	EXPORT RdLineRdLine	PROC****************************************************************** READ LINE:** Input     Word	 Space for result* Input     LongWord Pointer* Input     Word	 Count (max.)* Input     Word	 EOL character* Input     Word	 Echo flag (1=echo)* Output    Word	 Count (rcvd)*****************************************************************OrigDir	equ 1rtl1	equ OrigDir+2rtl2	equ rtl1+3Echo	equ rtl2+3EOLchar	equ echo+2count	equ EOLchar+2pointer	equ count+2rxcount	equ pointer+4	phd	; save direct page	tsc	; and turn stack into zp	tcd	stz RxCount	; initialize recv count	EXPORT LinLoopLinLoop		; 	pha	; room for character	lda echo	; pass echo flag to	rdchar	pha	jsl ReadIt	; read character	pla	; get character	bcs RlinErr	; if error occured	sep #$20	; 8 bit 'm'	cmp EOLchar	; are we done yet?	rep #$20	; 16 bit 'm'	beq done	; yes	xba	; save character	ldx pointer	; X=addr	sep #$20	; 8 bit m	longa off	phb	; save data bank	lda pointer+2	; get pointer bank	pha	plb	xba	; get char	sta |0,x	; send character to	buffer	plb	; restore data bank	rep #$20	; 16 bit m	longa on	inc pointer	; point at next	bne NoPtrOV	; if now overflow	inc pointer+2NoPtrOV		; 	inc RxCount	; increment bytes recvd	beq RLinErr	; if overflow, then	error	lda rxcount	cmp count	bne LinLoopDone		; 	jmp EndCall10	; else all done	EXPORT RLinErrRLinErr		; 	jmp ErrOut10	; oops	ENDPTTDsptch	PROC****************************************************************** This routine is called to dispatch to	both BASIC & PASCAL1.1* device drivers.  Input to this routine is as follows.....** ENTRY:*        16 bit 'm'	and 'x' native mode**      Input   Word	    Character (in low byte)* sp->*      A Register =	DEVICE DISPATCHER CONTROL BYTE  *      Y Register =	Driver type   0 = Input device*	              1 = Output device*	              2 = Error device** This routine returns with the CARRY bit set, and an error* code on the stack	if an error resulted from a dispatch to	the* BASIC, PASCAL1.1 or RAM BASED device driver.  If the call	was* to get input from	the device, the data will be returned on the* stack.  If the call was to send output to the device, the* data returned on the stack is unspecified.** EXIT:*        16 bit 'm'	and 'x' native mode**      Output  Word	    Returned data (in low byte)* sp->*      A Register =	Error code*      Carry = set for error, clear otherwise.  ** Low byte of Y register holds the DDCB	from the dispatch** The DEVICE DISPATCHER CONTROL BYTE is	defined as follows:**  ___ ___ ___ ___ ___ ___ ___ ___* |   |   |   |   |	  |   |   |   |* | 7 | 6 | 5 | 4 |	3 | 2 | 1 | 0 |* |___|___|___|___|___|___|___|___|*   |   |	|   |___|___|______	Call Type*   |   |	|	0 = Initialization*   |   |	|	1 = Read*   |   |	|	2 = Write*   |   |	|	3 = Status*   |   |	|	4 = Control*   |   |	|*   |   |___________|__________________	Driver Type*   |		0 = BASIC*   |		1 = PASCAL*   |*   |__________________________________	Driver SubType*		0 = STANDARD*		1 = ERROR*** Change History** 02 Aug 88	Steven Glass** This routine trys to return an error in the a-reg, if the* an initcall is being made to a device that is not there.** On other calls the a-reg was not set and carry was undefined.* Now, the a-reg will be zero if no error occurs and the * carry will be correct.** 16 Nov 88	Konstantin Othmer** Added support for slot arbiter by switching in proper slot.  I needed * a word to store the current slot configuration.  I get the space by* moving the return address and TheChar down one word and then sticking* the configuration where TheChar used to be.  The code at the very beginning* and very end of the routine handle the stack manipulation.*****************************************************************BInit	equ $C000	; BASIC init entryBInput	equ $FD0C	; BASIC input via rdkey entryBOutput	equ $FDED	; BASIC output via coutPInit	equ $C00D	; PASCAL init offsetPRead	equ $C00E	; PASCAL read offsetPWrite	equ $C00F	; PASCAL write offsetPStatus	equ $C010	; PASCAL status offsetPOption	equ $C011	; PASCAL option flagPControl	equ $C012	; PASCAL control offsetSaveHook	equ 1OrigStat	equ SaveHook+2DDCB	equ OrigStat+1OrigDir	equ DDCB+1OrigDB	equ OrigDir+2RTSaddr	equ OrigDB+1TheChar	equ RTSaddr+2	pha	;make room for slot config on stack	tax	;save DDCB	lda 3,s	;return address	sta 1,s	lda 5,s	;TheChar	sta 3,s;;now 5,s is empty and can be used to save slot configuration;	phx	;save DDCB (was in a)	phy	;save driver type;; Here we request the proper slot and save old configuration; on the stack (at 5,s).;		tya	; point at device pointer	and #$3	*** INPUT is messed up - requesting slot 3 for input?? ****	asl a	asl a	tax	lda |DevPtr,x	;get slot arbiter slot number (1-15)	and #$000f	jsl slot_arbiter	;set our slot configuration	txa	;old slot configuration to a		ply	plx	;get DDCB back 		sta 5,s	;save old slot configuration under 		;return address and TheChar	txa	;put DDCB back in a;; End of slot_arbiter stuff;		phb	; save dbr and d-reg	phd	sep #$20	; 8 bit 'm'	longa off;-----------------------------------------------------------;; Set the data banke to bank E1 and see what kind of device; it is;	pha	; save DDCB	pea DevPtr/256	; point at device type	plb	plb	lda |DevType,y	; get device type	cmp #2	; is it a ram based	driver ?	bne NotRB	; no;-----------------------------------------------------------;; Its a RAM driver.;	sep #$10	; 8 bit 'x'	longi off	tya	; point at device pointer	asl a	asl a	tax	rep #$10	; 16 bit 'x'	longi on	lda 1,s	; get DDCB	pha	; need its image	and #$07	; and make entry offset	sta 1,s	asl a	clc	adc 1,s	sta 1,s	; save entry offset	rep #$20	; 16 bit 'm'	longa on	and #$00FF	; offset is 16 bits	wide now	clc	adc |DevPtr,x	; calculate entry point	tay	lda #0	adc |DevPtr+2,x	tax	phk	; set dispatch return addr	pea RBret-1	sep #$20	; 8 bit 'm'	txa	; then set dispatch	address	pha	phy	rep #$20	; 16 bit 'm'	sec	lda 1,s	; really need addr-1	sbc #1	sta 1,s	sep #$20	; 8 bit 'm'	longa off	lda 3,s	sbc #0	sta 3,s	rep #$20	; 16 bit 'm'	longa on	lda 14,s	; get character for	driver		rtl	; dispatch to Ram driverRBret		; 	sta 8,s	; save the returned	character	sep #$20	; 8 bit 'm'	pla	pla	; clean off DDCB	tay	; DDCB must be in Y	on return	rep #$20	; 16 bit 'm'	brl NoErrorExit;-----------------------------------------------------------;; Its not a RAM driver, so its a BASIC or Pascal device;NotRB		; 	longa off	; were still in 8 bit 'm'	lda >StateReg	; save away state register	pha	lda #%00001000	; put in the ROM	sta >StateReg	pea $0000	; space for hooks	tsc	; turn stack into zp	tcd	lda #0	xba	; need B=$00	tya	; point at driver pointer	asl a	asl a	tay	lda DDCB	; get call type	and #$0F	asl a	tax	; point into dispatch table	bit DDCB	; V = Driver type	lda DDCB	; Z=1 if BASIC input call	dec a	rep #$30	; 16 bit 'm' & 'x'	longa on	longi on	bne NotBIn	; if not basic input	lda #BInput	; else set RDKEY	bra NoOffsetNotBIn		; 	sep #$20	; 8 bit 'm'	dec a	rep #$20	; 16 bit 'm'	bne NotBOut	; if not basic outputoutputb		; 	lda #BOutput	; else set COUT	bra NoOffsetNotBOut		; 	sep #$20	; is it a basic error output?	longa off	and #$0F	rep #$20	longa on	beq outputb	; yes	lda |DevPtr,y	; get driver pointer (slot);; Convert to regular slot number (1-7).  Slot arbiter numbers go 1-15;	and #$07	xba	; in high byte	ora #$C000	; make $Cn00	sep #$20	; 8 bit 'm'	phk	plb	ora |DTbl,x	; Addr = Root Addr + Slot	bvc NoOffset	; no offset if BASIC device	tax	; else point at offset byte	lda >0,x	; and get offsetNoOffset		; 	rep #$20	; 16 bit 'm'	longa on	pea TTDret-1	; return address	dec a	; need dispatch address-1	pha	inc a	xba	; need $Cn in X register	tax	asl a	; need $n0 in Y register	asl a	asl a	asl a	tay	lda 1,s	; get back dispatch	address	inc a	and #$FF00	; make it $Cn00	phx	; save dispatch X &	Y	phy	tax	bvc ChkBasic	; don't check PASCAL ID if BASICCkPascal		; 	sep #$20	; 8 bit 'm'	lda >5,x	; get PASCAL ID bytes	xba	lda >7,x	rep #$20	; 16 bit 'm'	longa on	cmp #$3818	; is signature OK?	beq DevOK	; yesBadDev		; 	rep #$30	; 16 bit 'm' & 'x'	longa on	longi on	pla	; clean off X	pla	; clean off Y	pla	; clean off dispatch addr	pla	; clean off TTRET-1	pla	; clean off HOOK space	sep #$30	; 8 bit 'm' & 'x'	longa off	longi off	pla	; restore state register	sta >StateReg	pla	; clean off DDCB	rep #$30	; 16 bit 'm' & 'x'	longa on	longi on	lda #IllegalDeviceError	; illegal device error	brl ErrorExitChkBasic		; 	sep #$20	; 8 bit 'm'	longa off	lda DDCB	; is it a BASIC read call?	and #$0F	dec a	beq DevOk	; yes	dec a	; is it a BASIC write call?	beq DevOk	; yes	ldy #10	lda >0,x	; read it once	beq BadDev	; cant be a BRKCKBloop		; 	cmp >0,x	; read rom	bne BadDev	; if not same, then	no device	dey	bpl CKBloop	; check a bunch of timesDevOk		; 	sep #$20	; 8 bit 'm'	longa off	ply	; restore dispatch X and Y	plx	bit DDCB	; get driver subtype	rep #$20	; 16 bit 'm'	longa on	bpl NotError	; if not an error driver	lda >CSW	; Save output hook	sta SaveHook	lda >ErrHook	; and set the error	hook	sta >CSWNotError		; 	lda TheChar	; get character to send	IF RAMVERSION=1 THEN	pha	pha	pha	pha	pha	phx	phy	lda  15,s	inc a	pha	_FWEntry	ply	plx	pla	plp	plp	sta  1,s	pla	;pull off the initial entry point	rts	ELSE	brl FWentry	; its time to dispatch	ENDIFTTDret		 	sta TheChar	; save return info	php	sep #$20	; 8 bit 'm'	longa off	lda DDCB	; get dispatch type	cmp #%01001011	; was it a PASCAL status	beq NotBRet	; if PASCAL status save C	plp	; else clear carry	clc	phpNotBRet		; 	sep #$20	; 8 bit 'm'	bit DDCB	; was it an error call?	rep #$20	; 16 bit 'm'	longa on	bpl NotErr	; if not an error driver	lda >CSW	; save error hook	sta >ErrHook	lda SaveHook	; restore output hook	sta >CSWNotErr		; 	plp	; restore return info	pla	; clean off hook space	sep #$20	; 8 bit 'm'	longa off	pla	; restore state reg	sta >StateReg	pla	; clean off DDCB	tay	; and save in low Y	rep #$30	; 16 bit 'm' & 'x'	longa on	longi onNoErrorExit	lda #0ErrorExit	cmp #1	pld	plb;; return slots to original configuration;	tax	;save error code	lda 5,s	;get original slot configuration	phx	;error code to stack	php		tax	phy	; ; Restore old slot configuration;	lda #$0300	;restore to configuration in x reg	jsl slot_arbiter	ply	plp	plx	;error code; Need to fix stack	lda 3,s	sta 5,s	;put TheChar back where it was	lda 1,s	sta 3,s	;put return address back	pla	;get empty space off	txa	;error code is returned in a reg.	sta $FF0010		rtsDTbl		; 	DC.W BInit	; BASIC init entry	DC.W BInput	; BASIC input entry	DC.W BOutput	; BASIC output entry	DC.W 0	DC.W 0	DC.W 0	DC.W 0	DC.W 0	DC.W PInit	; PASCAL init offset	DC.W PRead	; PASCAL read offset	DC.W PWrite	; PASCAL write offset	DC.W PStatus	; PASCAL status offset	DC.W PControl	; PASCAL control offset	DC.W 0	DC.W 0	DC.W 0	ENDP	EXPORT MakeDDCBMakeDDCB	PROC****************************************************************** This routine is to be called in native mode with 8 bit* 'm' and 'x'.  On entry, the accumulator should contain* the CALL TYPE, and the Y register should contain the* pointer to the DEVTYPE table entry for the device being* called.  The ouput contains the DDCB in the accumulator.** Y=$0000...Device is the input device* Y=$0001...Device is the standard output device* Y=$0002...Device is the error output device** Device types are as follows:*        $00 = BASIC*        $01 = PASCAL*        $02 = Ram based driver*****************************************************************	longa off	longi off	phb	pea DevType/256	; point at devtype table	plb	plb	pha	; save call type	lda |DevType,y	; get device type	beq GotDDCB	; if its basic	dec a	bne GotDDCB	; if its RAM based	pla	; else set pascal bit	ora #%01001000	pha	EXPORT GotDDCBGotDDCB		; 	cpy #2	; is it an error device?	bne NotErrD	; no	pla	; else set error dev bit	ora #%10000000	pha	EXPORT NotErrDNotErrD		; 	pla	; get DDCB off stack	plb	rts	ENDP	END